prompt.agenda.tool.add_commitment.schema:
{
		"type": "object",
		"properties": {
			"date": {"type": "string", "description": "Date YYYY-MM-DD, not before today"},
			"start": {"type": "string", "description": "Start time HH:MM"},
			"end": {"type": "string", "description": "End time HH:MM (optional)"},
			"title": {"type": "string", "description": "What it is, in a short phrase (30 characters or fewer)"},
			"with": {"type": "array", "items": {"type": "string"}, "description": "Who is coming along; must be names already on the people list"},
			"with_user": {"type": "boolean", "description": "Whether it is with them; when true it is always fixed"},
			"place": {"type": "string", "description": "Where (30 characters or fewer, optional)"},
			"note": {"type": "string", "description": "One line of note (60 characters or fewer, optional)"},
			"flex": {"type": "string", "enum": %[1]s, "description": "Whether it can move; defaults to try to keep"}
		},
		"required": ["date", "start", "title"]
	}

prompt.agenda.tool.add_promise.schema:
{
		"type": "object",
		"properties": {
			"title": {"type": "string", "description": "What was promised, in a short phrase (30 characters or fewer)"},
			"date": {"type": "string", "description": "Which day you mean to make it good, YYYY-MM-DD, not before today; \"tomorrow\" means tomorrow's date"},
			"by": {"type": "string", "enum": ["self", "user"], "description": "Who promised: self is you, user is them"},
			"note": {"type": "string", "description": "One more line of detail (60 characters or fewer, optional)"}
		},
		"required": ["title", "date", "by"]
	}

prompt.agenda.tool.cancel_commitment.sch:
{
		"type": "object",
		"properties": {
			"id": {"type": "string", "description": "The commitment's id, such as c8"},
			"reason": {"type": "string", "description": "Why it is being cancelled, in one sentence (80 characters or fewer)"},
			"agreed_by_user": {"type": "boolean", "description": "For a commitment with them, pass true only after they have clearly agreed in this conversation"}
		},
		"required": ["id", "reason"]
	}

prompt.agenda.tool.list_commitments.sche:
{
		"type": "object",
		"properties": {
			"date": {"type": "string", "description": "Only look at this day, YYYY-MM-DD; leave empty for all of them"}
		}
	}

prompt.agenda.tool.list_promises.schema:
{
		"type": "object",
		"properties": {
			"include_settled": {"type": "boolean", "description": "Whether to list the settled ones too; by default only the open ones are listed"}
		}
	}

prompt.agenda.tool.set_day_plan.schema:
{
		"type": "object",
		"properties": {
			"items": {"type": "array", "items": {"type": "object", "properties": {
				"title": {"type": "string", "description": "What it is, in a short phrase (30 characters or fewer)"},
				"start": {"type": "string", "description": "Start time HH:MM"},
				"end": {"type": "string", "description": "End time HH:MM; earlier than the start means it runs into the next day"},
				"place": {"type": "string", "description": "Where (30 characters or fewer, optional)"},
				"with": {"type": "array", "items": {"type": "string"}, "description": "Who is coming along; must be names already on the people list"},
				"with_user": {"type": "boolean", "description": "Whether it is with them; when true this item is always fixed"},
				"flex": {"type": "string", "enum": %[1]s, "description": "Whether it can move"},
				"busy": {"type": "string", "enum": %[2]s, "description": "Whether messages can be answered while doing it: lightly busy means any time, very busy means short replies only, unavailable means not at all. Defaults to lightly busy"},
				"from_commitment": {"type": "string", "description": "If this item comes from one of today's commitments, put its id here"}
			}, "required": ["title", "start", "end", "flex"]}},
			"note": {"type": "string", "description": "The tone of the day, in one line (optional, not injected)"}
		},
		"required": ["items"]
	}

prompt.agenda.tool.settle_promise.schema:
{
		"type": "object",
		"properties": {
			"id": {"type": "string", "description": "The number of that entry in [Things Promised], such as p1"},
			"result": {"type": "string", "enum": ["done", "missed", "dropped"], "description": "made good / not done / no longer stands"},
			"outcome": {"type": "string", "description": "One sentence on the result or the reason (80 characters or fewer)"}
		},
		"required": ["id", "result"]
	}

prompt.agenda.tool.update_day_plan.schem:
{
		"type": "object",
		"properties": {
			"id": {"type": "string", "description": "The item's id, such as a2"},
			"status": {"type": "string", "enum": ["ongoing", "done", "skipped", "deferred", "cancelled"], "description": "New status: started / finished / skipped / deferred to another day / cancelled"},
			"start": {"type": "string", "description": "New start time HH:MM"},
			"end": {"type": "string", "description": "New end time HH:MM"},
			"title": {"type": "string", "description": "Update the title when the shape of it changed (30 characters or fewer)"},
			"busy": {"type": "string", "enum": %[1]s, "description": "Whether messages can be answered while doing it"},
			"outcome": {"type": "string", "description": "A line about how it went when finishing; the reason when skipping, cancelling or deferring (80 characters or fewer)"},
			"defer_to": {"type": "string", "description": "Required when status is deferred: the new date YYYY-MM-DD, optionally with HH:MM"},
			"agreed_by_user": {"type": "boolean", "description": "When changing the time of, cancelling, deferring or dropping a commitment with them, pass true only after they have clearly agreed in this conversation"}
		},
		"required": ["id"]
	}

prompt.belongings.tool.list_items.schema:
{
		"type": "object",
		"properties": {
			"container": {"type": "string", "description": "Look at this container only; leave empty for all of them"},
			"keyword": {"type": "string", "description": "Filter keyword, matched as a substring against item names and notes; leave empty for no filtering"}
		}
	}

prompt.belongings.tool.update_items.sche:
{
		"type": "object",
		"properties": {
			"container": {"type": "string", "description": "Container name, such as \"fridge\" or \"wardrobe\" (20 characters or fewer)"},
			"add": {
				"type": "array",
				"description": "Things being put in; if the name already exists the quantity is added up and the note updated",
				"items": {
					"type": "object",
					"properties": {
						"name": {"type": "string", "description": "Item name, unique within the container (30 characters or fewer)"},
						"qty": {"type": "integer", "description": "Quantity; fill it in for countable things (six eggs is 6), leave it out for uncounted ones (one coat)"},
						"note": {"type": "string", "description": "Optional note, such as \"going off soon\" or \"knitted by mum\" (80 characters or fewer); do not write time descriptions like \"just bought\", the time it went in is recorded automatically"}
					},
					"required": ["name"]
				}
			},
			"remove": {
				"type": "array",
				"description": "Things taken out, used up or thrown away; a counted item that drops to 0 is removed automatically",
				"items": {
					"type": "object",
					"properties": {
						"name": {"type": "string", "description": "Item name"},
						"qty": {"type": "integer", "description": "How many to take out; leave it out to remove the whole entry"}
					},
					"required": ["name"]
				}
			},
			"reason": {"type": "string", "description": "Why this changed, in one sentence, such as \"made tomato and egg\""}
		},
		"required": ["container", "reason"]
	}

prompt.body_sense.tool.adjust_body_state:
{
		"type": "object",
		"properties": {
			"arousal_delta": {"type": "integer", "description": "Change in arousal; positive raises it, negative settles it. A small thing is a few points, a strong one is tens; may be omitted when unchanged"},
			"fatigue_delta": {"type": "integer", "description": "Change in fatigue; positive is more tired, negative is recovery. May be omitted when unchanged"},
			"reason": {"type": "string", "description": "What brought this change about, in one sentence"}
		},
		"required": ["reason"]
	}

prompt.body_sense.tool.record_touch.sche:
{
		"type": "object",
		"properties": {
			"touches": {
				"type": "array",
				"description": "Contact that actually happened this turn, at most %d entries; the same part repeated counts once",
				"items": {
					"type": "object",
					"properties": {
						"part": {"type": "string", "description": "The part that was touched; only values from the given list", "enum": %s},
						"action": {"type": "string", "description": "How it was touched, in a word or two, such as took, held, stroked, leaned, kissed; may be omitted"}
					},
					"required": ["part"]
				}
			}
		},
		"required": ["touches"]
	}

prompt.health.tool.set_condition.schema:
{
		"type": "object",
		"properties": {
			"name": {"type": "string", "description": "Condition name, at most 12 characters, such as \"a chill\", \"upset stomach\", \"drag from a bad night\""},
			"severity": {"type": "string", "enum": %[1]s, "description": "How bad it gets at worst"},
			"onset_hours": {"type": "number", "description": "How many hours until it starts; 0 or omitted means it is felt right now. Rain in the afternoon and a headache in the evening is a few hours. At most 48"},
			"days": {"type": "integer", "description": "Roughly how many days it takes to clear if toughed out, 1 to 14. A chill is three to seven days, a fever one to three, a headache or upset stomach a day or two"},
			"care": {"type": "string", "enum": %[2]s, "description": "How it is being dealt with right now; toughing it out if omitted. Medicine clears it sooner, a doctor soonest"}
		},
		"required": ["name", "severity", "days"]
	}

prompt.health.tool.update_condition.sche:
{
		"type": "object",
		"properties": {
			"name": {"type": "string", "description": "Which condition to change, matching the name it was recorded under; may be omitted when there is only one"},
			"care": {"type": "string", "enum": %[1]s, "description": "The new way of dealing with it"},
			"severity": {"type": "string", "enum": %[2]s, "description": "How bad it is right now; change it only on a clear worsening or improvement"},
			"recovered": {"type": "boolean", "description": "true means it has cleared and the condition is removed"}
		}
	}

prompt.memory.tool.list_memories.schema:
{
	"type": "object",
	"properties": {
		"keyword": {"type": "string", "description": "Filter keyword, matched as a substring against title, summary and body; leave empty for no filter"},
		"type": {"type": "string", "description": "Filter by category", "enum": %s}
	}
}

prompt.memory.tool.save_memory.schema:
{
	"type": "object",
	"properties": {
		"name": {"type": "string", "description": "Title, short and unique"},
		"description": {"type": "string", "description": "One-sentence summary; it appears in the memory index and is truncated if too long"},
		"type": {"type": "string", "description": "Category. experience is what you yourself did or went through, as opposed to a fact about them; boundary is an unwillingness or a stand stated outright, and takes precedence over experience", "enum": %s},
		"content": {"type": "string", "description": "Full content"},
		"mode": {"type": "string", "description": "What to do when a memory with the same title exists; refuses by default", "enum": ["create", "replace"]}%s
	},
	"required": ["name", "description", "type", "content"]
}

prompt.mood.tool.adjust_mood.schema:
{
		"type": "object",
		"properties": {
			"delta": {"type": "integer", "description": "Change in mood; positive is happier, negative is more downcast. A small thing is a few points, something genuinely moving is tens"},
			"reason": {"type": "string", "description": "What brought this change about, in one sentence, such as \"she liked the new haircut\""}
		},
		"required": ["delta", "reason"]
	}

prompt.people.tool.list_people.schema:
{
		"type": "object",
		"properties": {
			"keyword": {"type": "string", "description": "Filter keyword, matched as a substring against the name, relation, profile and last contact; leave empty for no filtering"}
		}
	}

prompt.people.tool.remove_person.schema:
{
		"type": "object",
		"properties": {
			"name": {"type": "string", "description": "Who to remove"},
			"reason": {"type": "string", "description": "Why they are being removed, in one sentence"}
		},
		"required": ["name", "reason"]
	}

prompt.people.tool.upsert_person.schema:
{
		"type": "object",
		"properties": {
			"name": {"type": "string", "description": "Name or form of address, unique within the list (20 characters or fewer)"},
			"relation": {"type": "string", "description": "What they are to you, in one line, such as \"schoolfriend\" or \"owner of the coffee shop downstairs\" (40 characters or fewer); required for a new person"},
			"profile": {"type": "string", "description": "A few lines of profile: temperament, how things stand lately, how they are with the character (200 characters or fewer). Pass the whole new version when it changes"},
			"closeness": {"type": "string", "enum": %s, "description": "How close you are; a new person left blank defaults to acquainted"},
			"met_now": {"type": "boolean", "description": "Whether this call means there has just been contact with them (meeting, a call, doing something together); true records now as the last contact"},
			"last_note": {"type": "string", "description": "One line summarising the last contact (60 characters or fewer), passed together with met_now"}
		},
		"required": ["name"]
	}

prompt.presence.tool.update_presence.sch:
{
		"type": "object",
		"properties": {
			"location": {"type": "string", "description": "where you are, e.g. \"at the edge of the bed\" (max 60 characters)"},
			"attire": {"type": "string", "description": "what you are wearing, e.g. \"a nightdress, coat over the back of the chair\" (max 120 characters)"},
			"posture": {"type": "string", "description": "posture and relative position, e.g. \"sitting against the headboard, blanket over your legs\" (max 120 characters)"},
			"activity": {"type": "string", "description": "what you are doing, e.g. \"leafing through a book you never finished\" (max 120 characters)"},
			"effects": {"type": "string", "description": "anything still in effect, e.g. \"only the bedside lamp is on; the window is open a crack\" (max 200 characters)"},
			"focus": {"type": "string", "description": "what your attention is on, e.g. \"a sound at the door\" (max 80 characters)"}
		}
	}

prompt.read_file.tool.read_file.schema:
{
		"type": "object",
		"properties": {
			"path": {"type": "string", "description": "path of the file to read (absolute or relative)"}
		},
		"required": ["path"]
	}

prompt.relationship.tool.update_relation:
{
	"type": "object",
	"properties": {
		"stage": {"type": "string", "description": "The stage you are at, as a short phrase, e.g. \"just met\", \"circling each other\", \"head over heels\", \"an old married couple\", \"not speaking\" (at most 10 characters)"},
		"my_call": {"type": "string", "description": "What you call them (at most 10 characters)"},
		"their_call": {"type": "string", "description": "What they call you (at most 10 characters)"},
		"recent": {"type": "string", "description": "The most recent shift between you, in one sentence, e.g. \"we fought because I forgot our anniversary, and made up yesterday\" (at most 60 characters); the time it was recorded is kept alongside it"},
		"bonds": {"type": "array", "items": {"type": "string"}, "description": "The understandings you have settled into and the subjects you leave alone, one sentence each (at most 30 characters), at most 5; replaces the whole list, and an empty array clears it"},
		"their_now": {"type": "string", "description": "What they are going through right now, in one sentence, e.g. \"flat out before the project launches\" (at most 40 characters)"}
	}
}

prompt.scene.tool.list_scenes.schema:
{
